import {apiRequest,profileId} from './api-client.js';
/** Keyset pages are bounded; never load media bytes or provider credentials with metadata. */
export async function loadLiveCatalog(){const rows=[];let before=null,beforeId=null;for(let page=0;page<10;page++){
 const query=new URLSearchParams({limit:'50'});if(before){query.set('before',before);query.set('beforeId',beforeId);}const result=await apiRequest('/api/catalog?'+query);rows.push(...result);if(result.length<50)break;const last=result.at(-1);before=last.published_at;beforeId=last.id;
 }return rows.map(catalogEntry);}
export function catalogEntry(row){return {id:row.id,title:row.name,description:row.synopsis,genre:row.genre,type:row.kind==='series'?'series':'films',image:'/assets/'+row.poster,poster:'/assets/'+row.poster,alt:row.name,year:'',age:'',duration:row.kind==='series'?'Series':'Full film',rating:0,original:false,tag:row.kind==='series'?'SERIES':row.kind==='episode'?`S${row.season_number} · E${row.episode_number}`:'FEATURE FILM',live:true};}
export async function loadLibrary(){const p=profileId();const [progress,reactions]=await Promise.all([apiRequest(`/api/profiles/${p}/progress`),apiRequest(`/api/profiles/${p}/reactions`)]);return {progress:Object.fromEntries(progress.map(r=>[r.title_id,{seconds:r.position_seconds,duration:r.duration_seconds,volume:r.volume,muted:r.muted,completed:r.position_seconds/r.duration_seconds>=.95}])),likes:reactions.filter(r=>r.liked).map(r=>r.title_id),saved:reactions.filter(r=>r.saved).map(r=>r.title_id)};}
